INSERT INTO `daily_ai_insights` (`id`, `user_id`, `insight_date`, `ai_text`, `created_at`, `updated_at`) VALUES
(1, 2, '2026-01-16', 'Sapmashi haramkhori mein taqat daam badh gayi hai, kamayi barabar rakhnge to bachat kam hogi.', '2026-01-16 15:08:31', '2026-01-16 15:08:31'),
(2, 2, '2026-01-20', 'Agar aapko pata chahiye kyun tumhari kul aghosh 0 rupaye hai, to is kaa sabab sarf-e-rujhanian hai.', '2026-01-20 14:55:26', '2026-01-20 14:55:26'),
(3, 2, '2026-01-21', 'Agar aapko paise bachane ki zaroorat hai to is haal mein kam kharch karein.', '2026-01-21 06:34:43', '2026-01-21 06:34:43'),
(4, 2, '2026-01-22', 'Sapmashi haramzade zyada barhti hui inflation ke saath apni kharchain band kar lo.', '2026-01-22 06:17:25', '2026-01-22 06:17:25'),
(5, 2, '2026-01-23', 'Agar aapko pata chahiye ke saal ke baad aapki kharchon ki inflation kya hai, to is sal ki sabse bada kharch hai gas ke.', '2026-01-23 10:21:41', '2026-01-23 10:21:41'),
(6, 2, '2026-01-25', 'Aapka khaas haftay ka kharch 10000 rupiye se zyada ho gaya hai, agli haftay mein yeh trend kam karo.', '2026-01-25 06:28:12', '2026-01-25 06:28:12'),
(7, 2, '2026-01-27', 'Agar aapko pata chahiye kyun savaal dhundla hai, to dekhiye inflation ne aapki rujhan badli hai.', '2026-01-27 10:50:57', '2026-01-27 10:50:57'),
(8, 2, '2026-01-28', 'Agar aapko paison ki halat samajhni hai to is hafte ke ghatnaon ko dekhiye, khaas kar savings ko kam ki khabar rakhiye.', '2026-01-28 14:23:26', '2026-01-28 14:23:26'),
(9, 6, '2026-01-28', 'Sede dil, aisay kharchaan se inflation ko badhaya ja raha hai.', '2026-01-28 17:12:39', '2026-01-28 17:12:39'),
(10, 6, '2026-01-29', 'Agar aap kay hissabon mein zyada barhti hui inflaation ko chunauti nahi karna, medical expenses kam karain.', '2026-01-29 07:51:41', '2026-01-29 07:51:41'),
(11, 8, '2026-01-29', 'Ajkal mehngai barh rahi hai, utilities mein sabse zyada paisa jaa raha hai.', '2026-01-29 08:43:14', '2026-01-29 08:43:14'),
(12, 2, '2026-01-29', 'Agar aapko kharcha ki ahammiyat hai to is baar kay mahine mein kuch nahi kharch kiya hai.', '2026-01-29 09:27:36', '2026-01-29 09:27:36'),
(13, 8, '2026-01-31', 'Aisaa inflayion hai ke saari kamaiyon ke paas khaali choot gaya hai, Utilities mein sabse zyada paisa barbaad ho gaya hai.', '2026-01-31 14:35:12', '2026-01-31 14:35:12'),
(14, 2, '2026-02-04', 'Aap kay savings ka kamzori hai, is sal ki inflation se paresnaney zaroori.', '2026-02-04 16:12:09', '2026-02-04 16:12:09'),
(15, 2, '2026-02-06', 'Aap ke khaas kamayi mein se bohot kam kamai rahi hai, isliye bachat ka kamyabi nahi hai.', '2026-02-06 06:27:56', '2026-02-06 06:27:56'),
(16, 9, '2026-02-08', 'Apne paisey Bartan daam badhne se kam hokar bachao (Save your money from increasing grocery prices).', '2026-02-08 15:05:10', '2026-02-08 15:05:10'),
(17, 2, '2026-02-12', 'Aapki kifayati madad ke liye kamyaabi ka irada rakhiye, kyunki inflation aapki kharchoon ko barhai hai.', '2026-02-12 10:31:58', '2026-02-12 10:31:58'),
(18, 2, '2026-02-17', 'Sapmashi haramzade zamaney mein, savings kam hain.', '2026-02-17 10:53:35', '2026-02-17 10:53:35'),
(19, 2, '2026-02-18', 'Agar aapko kharchon ki inflation ki pehchan Adhuri hai, to is waqt dekhiye apne kharchon ki trend.', '2026-02-18 08:00:43', '2026-02-18 08:00:43'),
(20, 2, '2026-03-04', 'Sapling zyada paisa chal raha hai, savings ko nazar andaz rakhein.', '2026-03-04 10:27:25', '2026-03-04 10:27:25'),
(21, 2, '2026-03-28', 'Savings kam ho rahi hain, inflation se panga lena zaroori nahi.', '2026-03-28 08:49:44', '2026-03-28 08:49:44'),
(22, 8, '2026-03-28', 'Aap ki khaas taur par mahine mein kharcha kam hai lekin inflation ka nuksan sammat nahi.', '2026-03-28 10:03:25', '2026-03-28 10:03:25'),
(23, 2, '2026-03-29', 'Agar aapko yaad hai, savings kam kiye jate hain, inflation barhti jari hai.', '2026-03-29 07:28:09', '2026-03-29 07:28:09'),
(24, 2, '2026-04-03', 'Aapke kharcha mein haftay ki barhti hai, savings ko nazar andaz rakhein.', '2026-04-03 12:50:38', '2026-04-03 12:50:38'),
(25, 2, '2026-04-05', 'Aap kay saare mahine ki kharchein inflation se barhtein hain, sachmuch dhyan do.', '2026-04-05 10:26:32', '2026-04-05 10:26:32'),
(26, 2, '2026-04-16', 'Aap ke khaas tarah ke kharchon mein \'ghar ka kharcha\' zyada hai. Dhyaan dein inflation ka faeda uthane se.', '2026-04-16 11:27:18', '2026-04-16 11:27:18');
INSERT INTO `daily_money_snapshots` (`id`, `snapshot_date`, `expense_summary_text`, `inflation_status_text`, `saving_tip_text`, `today_update_line`, `yesterday_change_line`, `source_metadata`, `kharcha_cta_label`, `kharcha_cta_url`, `ration_cta_label`, `ration_cta_url`, `last_updated_at`, `created_at`, `updated_at`) VALUES
(1, '2026-01-16', '“پاکستان میں مجموعی مہنگائی 5.6 فیصد سال‌ بہ‌ سال ریکارڈ کی گئی ہے، جبکہ ماہ‌ بہ‌ ماہ قیمتیں معمولی کمی پر ہیں۔ شہریوں کیلئے خوراک اور غیر‌مجلد خدمات کی قیمتوں میں نرمی دیکھی گئی ہے، مگر رہائش اور یوٹیلیٹی اخراجات پر دباو برقرار ہے.', 'قابلِ تشویش اشیائے خورو نوش کا ہفتہ وار حساس قیمت انڈیکس (SPI) 0.12 فیصد بڑھا ہے، جو بتاتا ہے چند اشیاء کی قیمتیں ہفتہ وار سطح پر اوپر جا رہی ہیں. چینی، کوکنگ آئل اور دالوں جیسے اسٹاپلز میں اتارچڑھاؤ کا رجحان جاری ہے.”', 'کھانا پکانے کے تیل اور پھل و سبزی کی قیمتیں گزشتہ مدت کی نسبت نرم ہیں، جس سے بنیادی خوراک پر ماہانہ بجٹ میں کچھ راحت مل سکتی ہے. ماہانہ کھانے پینے کی اشیاء کے اخراجات پر نظر رکھنے سے بچت کا موقع بڑھ سکتا ہے.', 'مودی تازہ CPI ڈیٹا کے مطابق سالانہ انفلیشن سست ہوکر 5.6 فیصد ہو گئی ہے، جو گزشتہ ماہ 6.1 فیصد تھی — قلیل مدت میں قیمتوں پر کچھ سکون ہے', 'گزشتہ ماہ کے مقابلے میں مہنگائی کی رفتار میں کمی دیکھی گئی ہے، خاص طور پر خوراک اور غیر‌مجمد خدمات کے اخراجات میں نرمی آئی ہے، جس سے گھریلو بجٹ پر دباو تھوڑا کم ہوا ہے', NULL, 'اپنا خرچ یہاں دیکھیں', 'https://roznamcha.pk/kharcha-map', 'اپنا ماہانہ بجٹ بنائیں', 'https://roznamcha.pk/ration-brain', '2026-01-16 15:09:19', '2026-01-16 15:09:19', '2026-01-16 15:09:19'),
(2, '2026-01-20', 'گھر کے اخراجات آج بھی حالیہ مارکیٹ رپورٹس کے مطابق پچھلے ہفتے کی طرح متوازن رہنے کی امید ہے۔', 'تازہ CPI کے مطابق مہنگائی کی رفتار 12.6% ہے، اس لیے ہفتے کے پلان میں تھوڑا بفر رکھیں۔', 'گھر کا ماہانہ بجٹ اپ ڈیٹ کریں تاکہ اچانک بل آنے پر کنٹرول رہے۔', 'آج کی صورتحال مستحکم ہے، گھر کا خرچ لاگ بک ضرور اپ ڈیٹ کریں۔', 'کل کے مقابلے میں بڑے فرق کی اطلاع نہیں ملی، پھر بھی خریداری کی فہرست مختصر رکھیں۔', '{\"inflation\":{\"value\":12.6325318530452,\"source\":\"https:\\/\\/api.worldbank.org\\/v2\\/country\\/PAK\\/indicator\\/FP.CPI.TOTL.ZG?format=json&per_page=1\",\"fetched_at\":\"2026-01-20T14:56:03+00:00\"},\"snapshot_generated_for\":\"2026-01-20\"}', NULL, NULL, NULL, NULL, '2026-01-20 14:56:08', '2026-01-20 14:56:08', '2026-01-20 14:56:08'),
